import json, glob, os, re, hashlib, collections
ROOT = '/home/user/chats-work/chats'

def raw_user_texts(d):
    """User messages, RAW content (only outer strip) - no unescape, no ws collapse."""
    if 'evaluation' in d:
        msgs = d['evaluation'].get('messages', [])
        return [ (m.get('content') or '').strip() for m in msgs if m.get('role')=='user' ]
    else:
        out = []
        for m in d['agent'].get('messages', []):
            if m.get('role')=='user':
                out.append(' '.join(p.get('text','') for p in m.get('parts',[]) if p.get('type')=='text').strip())
        return out

def raw_asst(d):
    if 'evaluation' in d:
        return [ ((m.get('content') or '').strip(), m.get('modelId'), m.get('status')) for m in d['evaluation'].get('messages',[]) if m.get('role')=='assistant' ]
    else:
        out = []
        for m in d['agent'].get('messages', []):
            if m.get('role')=='assistant':
                t = ' '.join(p.get('text','') for p in m.get('parts',[]) if p.get('type')=='text').strip()
                out.append((t, m.get('modelId'), m.get('status')))
        return out

def h(s): return hashlib.sha256(s.encode()).hexdigest()[:16]

chats = []
for p in sorted(glob.glob(os.path.join(ROOT,'**','chat.json'), recursive=True)):
    d = json.load(open(p, encoding='utf-8'))
    rel = os.path.relpath(os.path.dirname(p), ROOT)
    chats.append({'path': rel, 'users': raw_user_texts(d), 'assts': raw_asst(d)})

by_input = collections.defaultdict(list)
for c in chats:
    by_input[h('\x00'.join(c['users']))].append(c)
groups = [g for g in by_input.values() if len(g) > 1]
print(f'RAW-hash same-input groups: {len(groups)} (members: {sum(len(g) for g in groups)})')
for g in sorted(groups, key=lambda g:-len(g)):
    # outcome matrix: distinct (text,model,status) combos
    outs = collections.Counter((h(t), m, s) for c in g for (t,m,s) in c['assts'])
    models = collections.Counter(m for c in g for (t,m,s) in c['assts'])
    statuses = collections.Counter(s for c in g for (t,m,s) in c['assts'])
    print(f"\nGROUP x{len(g)}: outcomes={len(outs)} distinct | statuses={dict(statuses)}")
    for c in g:
        a_desc = '; '.join(f'{m} [{s}] {len(t)}ch' for (t,m,s) in c['assts'])
        print(f"  {c['path'].split('/')[-1][:60]:60s} | {a_desc[:110]}")

# same input AND same outcome but different model? (would be even safer merges)
print('\n=== same input, identical outcome text, DIFFERENT model (cross-model dupes) ===')
found = 0
for g in groups:
    by_text = collections.defaultdict(set)
    for c in g:
        for (t,m,s) in c['assts']:
            by_text[h(t)].add(m)
    for t, ms in by_text.items():
        if len(ms) > 1:
            found += 1
            print('  cross-model identical outcome among:', [c['path'].split('/')[-1][:40] for c in g], 'models:', ms)
print('none' if not found else f'{found} cases')

# full raw duplicates
by_full = collections.defaultdict(list)
for c in chats:
    by_full[h('\x00'.join(c['users']) + '\x01' + '\x00'.join(t for (t,m,s) in c['assts']))].append(c)
fdups = [g for g in by_full.values() if len(g)>1]
print(f'\nRAW full-duplicate groups: {len(fdups)}')
for g in fdups:
    for c in g: print('  ', c['path'])
