// cyrb53 — small deterministic string hash. Not cryptographic; it only has
// to group byte-identical user inputs within one export batch.
function fingerprintText(text) {
  const str = String(text || "");
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i += 1) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, "0") + (h1 >>> 0).toString(16).padStart(8, "0");
}

function normalizeForFingerprint(text) {
  return String(text || "").replace(/\s+/g, " ").trim();
}

// The full sequence of user turns, whitespace-normalised. Two chats with the
// same fingerprint were sent the same input (usually to compare models or
// after a failed generation) — they are safe merge candidates.
function getUserInputText(record) {
  const messages = Array.isArray(record?.messages) ? record.messages : [];
  const userTexts = messages
    .filter((message) => String(message?.role || "").toLowerCase() === "user")
    .map((message) =>
      normalizeForFingerprint(
        isAgentExportObject(record)
          ? getTextFromAgentParts(message?.parts) ||
              normalizeContent(message?.content || message?.text)
          : normalizeContent(message?.content)
      )
    );
  return userTexts.join("\n---\n");
}

