// Agent messages carry no createdAt — only metadata.timing.completedAt —
// and the payload reports pagination.hasMore=true.
function agentPageHtmlTimed(id) {
  const flight = [
    `3:{"session":{"id":"${id}","title":"Timed agent chat",`,
    `"createdAt":"2026-09-25T08:00:00.000Z","updatedAt":"2026-09-25T09:00:00.000Z"},"messages":[`,
    `{"id":"m1","metadata":{"manifestNodeId":"n1","nodeId":"m1","pending":false,"requiresReview":false,"feedback":{}},"role":"user","parts":[{"type":"text","text":"hello agent"}]},`,
    `{"id":"m2","metadata":{"timing":{"completedAt":1790156651083},"manifestNodeId":"n1","nodeId":"m2","pending":false,"requiresReview":false,"feedback":{}},"role":"assistant","parts":[{"type":"text","text":"timed answer"}]}],`,
    `"pagination":{"hasMore":true,"cursor":"cursor-xyz","limit":20}}`,
  ].join("");
  return `<html><body><script>self.__next_f.push([1, ${JSON.stringify(flight)}])</script></body></html>`;
}

